/**
 * @ohos/dsh-sanguo — a playable Three Kingdoms life simulation, as tools.
 *
 * WHY THIS IS A PLUGIN AND NOT A WORKSPACE SCRIPT
 *
 * The obvious design is "put the engine in the agent's workspace and let the
 * model run it". That cannot work here: this profile runs `tools.mode: native`,
 * where `run_code` is NOT in the model's tool table (dsh-tools only injects it
 * when mode !== native), and `bash` is patched out because HarmonyOS forbids
 * fork/exec. A JS file in the workspace is a dead file — nothing can execute it.
 *
 * So the engine ships as a plugin and the model talks to it through five tools.
 * That is not a workaround; it is the correct split. The engine is the referee,
 * the model is the narrator, and they meet at a narrow, validated interface.
 *
 * THE CONTRACT (repeated in every tool description, because it must survive
 * being read out of order):
 *
 *   · Every outcome comes from the engine. The model never decides whether
 *     something worked, how much gold moved, or who remembers what.
 *   · The model may suggest an attribute and a difficulty. Both are clamped to
 *     a legal band before any die is rolled, so a hint can nudge a check but
 *     can never make success automatic or impossible.
 *   · Every mutating tool returns a fresh digest, so the model never needs a
 *     second round-trip to re-read state. On this device a round-trip is 2-3
 *     seconds; paying it every turn would make the game unplayable.
 *   · The save lives in the session workspace (`.sanguo/save.json`), is atomic
 *     (temp + rename), and is append-only in history. A run can be inspected,
 *     copied, and resumed.
 */

import z from '@deepseek-ai/schemastery'
import { defineTool } from '@deepseek-ai/dsh-tools'
import { HarnessError } from '@deepseek-ai/dsh-llm'
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises'
import { join } from 'node:path'

import { buildDigest, renderDigest } from './engine/digest.js'
import {
  createSave, load, save, appendHistory, exists, migrate, SAVE_DIR
} from './engine/state.js'
import { formatDate, eraOf } from './engine/clock.js'
import { describe as describeDrift } from './engine/destiny.js'
import {
  indexActs, currentScene, describeScene, chooseBranch, attemptScene,
  advanceWorld, nextCursor, pushLog, rosterOf, seedFactions, catchUpToScene
} from './engine/acts.js'
import { ensurePerson, putPerson, remember, dispositionOf, stanceLabel } from './engine/people.js'

const name = 'tool-sanguo'
const inject = ['tools', 'systemPrompt', 'workingDirectory']

/**
 * Config is declared but currently empty of tunables.
 *
 * The knobs that matter (drift pricing, pressure cap, difficulty bands) live in
 * the engine modules as exported constants on purpose: they are design values,
 * not deployment settings, and a YAML override that silently changed the dice
 * would make two runs incomparable.
 */
const Config = z.object({})

/** Where the act table lives, relative to this package. */
const ACTS_FILE = 'acts.json'

/** Guard: a single advance may not skip more than two years of seasons. */
const MAX_ADVANCE_TURNS = 8

/**
 * Engine failures carry a stable code so the model can tell "you asked for a
 * scene that does not exist" (a fixable mistake) apart from "the save is
 * corrupt" (stop and tell the player).
 */
var SanguoError = class extends HarnessError {
  code
  constructor(message, code, options) {
    super(message, code, options)
    this.code = code
  }
}

/** Resolve the session workdir the same way the stock fs tools do. */
async function resolveWorkdir(ctx, exec) {
  return exec.agent === void 0 ? process.cwd() : await ctx.workingDirectory.ensure(exec.agent, exec.signal)
}

/** Load the act table once per process. It is static content, not save state. */
let actsCache = null

async function loadActs() {
  if (actsCache !== null) {
    return actsCache
  }
  const path = join(import.meta.dirname, 'data', ACTS_FILE)
  const text = await readFile(path, 'utf8')
  actsCache = indexActs(JSON.parse(text))
  return actsCache
}

/**
 * Read the save, or explain clearly that there is none.
 *
 * "Start a game first" is a much better answer than an empty digest, because an
 * empty digest invites the model to invent a world.
 */
async function requireSave(workdir) {
  const state = await load(workdir)
  if (state === null) {
    throw new SanguoError(
      '还没有开局。先调用 sanguo_new 开始一局（或 sanguo_status 查看是否已有存档）。',
      'SANGO_NO_SAVE'
    )
  }
  return state
}

/**
 * Persist and return the digest, which every mutating tool hands back.
 *
 * Also refreshes `.sanguo/life.json`: the card projection. It is derived state,
 * never a source of truth — the save is — but writing it here means a future
 * CardRenderer has something to read without the model having to remember to
 * update a second file (which it would eventually forget).
 */
async function commit(workdir, state, extra, record) {
  const stamped = { ...state, updatedAt: new Date().toISOString() }
  await save(workdir, stamped)
  if (record !== undefined) {
    await appendHistory(workdir, record)
  }
  const digest = buildDigest(stamped, extra)
  await writeProjection(workdir, digest, extra)
  return { state: stamped, digest }
}

/**
 * Shape the pending scene for the projection.
 *
 * Only the fields a board can render survive: title, narration, kind, and for a
 * moral node its options with their declared effects. A 30 KB act table entry
 * must not leak into a file the UI reads on every turn.
 */
function projectionScene(pending) {
  if (pending === null || pending === undefined || pending.finished === true) {
    return { finished: true, title: '', narration: '', kind: '', options: [] }
  }
  const options = Array.isArray(pending.options)
    ? pending.options.map((option) => ({
      id: option.id,
      label: option.label,
      note: option.note ?? '',
      effects: option.effects ?? {}
    }))
    : []
  return {
    finished: false,
    act: pending.act ?? '',
    title: pending.title ?? '',
    narration: pending.narration ?? '',
    kind: pending.kind ?? '',
    attribute: pending.attribute ?? '',
    difficulty: Number.isFinite(pending.difficulty) ? pending.difficulty : 0,
    options
  }
}

/**
 * Write the card projection. Failure here must never fail a turn.
 *
 * The projection carries the CURRENT SCENE and its options, not just the
 * numbers. Without them a native front end could render a status board but the
 * player would still have to go back to the chat transcript to choose — which
 * defeats the point of having a board at all.
 */
async function writeProjection(workdir, digest, extra) {
  try {
    const dir = join(workdir, SAVE_DIR)
    await mkdir(dir, { recursive: true })
    const target = join(dir, 'life.json')
    const body = JSON.stringify({
      when: digest.when,
      age: digest.age,
      place: digest.place,
      act: digest.act,
      counters: digest.me.counters,
      resources: digest.me.resources,
      world: digest.world,
      people: digest.people.map((person) => ({ name: person.name, stance: person.stance })),
      // The pending scene is what the board renders as actions. `extra.pending`
      // is the same object the tool returned, so the board and the transcript
      // can never disagree about which options are on offer.
      scene: projectionScene(extra?.pending),
      generatedAt: new Date().toISOString()
    }, null, 2)
    const staging = `${target}.${process.pid}.tmp`
    await writeFile(staging, body, 'utf8')
    await rename(staging, target)
  } catch (error) {
    // A card projection is cosmetic; never let it break the game.
  }
}

/** Shape one scene for the model. */
function scenePayload(state, acts) {
  const { act, scene } = currentScene(state, acts)
  if (scene === null) {
    return {
      act: act?.name ?? '',
      actId: act?.id ?? '',
      sceneId: '',
      finished: true,
      text: '这一段落已尽。可以推进时间（sanguo_advance）或自由行动（sanguo_act）。'
    }
  }
  const described = describeScene(act, scene, state)
  return { ...described, finished: false }
}

/**
 * Register the five tools.
 *
 * Five, not fifteen, on purpose: each tool the model must choose between costs
 * it a decision, and every extra tool dilutes the descriptions that keep it
 * inside the contract. The set below covers open / look / choose / act / wait.
 */
function apply(ctx, config) {
  registerNew(ctx)
  registerStatus(ctx)
  registerChoose(ctx)
  registerAct(ctx)
  registerAdvance(ctx)
}

/** Keep the human-readable act name and place in step with the cursor. */
function restamp(state, acts, previous) {
  const act = acts.get(state.act)
  return {
    ...state,
    actName: act?.name ?? state.actName ?? previous?.actName ?? '',
    place: state.place ?? act?.place ?? previous?.place ?? ''
  }
}

/** sanguo_new — start a run. */
function registerNew(ctx) {
  const tool = defineTool({
    name: 'sanguo_new',
    description:
      '开始一局新的三国人生模拟（玩家扮演刘备，从184年涿郡起兵开始）。' +
      '会覆盖同一工作区里已有的存档。开局后必须用返回的 digest 描述处境，不要自行编造世界状态。' +
      '仅在玩家明确说「开始新的一局/重开」时调用。',
    parameters: {
      name: {
        type: 'string',
        description: '存档名。同名开局会得到完全相同的随机序列（可用于复盘同一局）。缺省为 liubei。'
      }
    },
    output: {
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          digest: { type: 'json', required: true },
          scene: { type: 'json', required: true },
          rendered: { type: 'string', required: true }
        }
      },
      render: (_args, value) => [{ type: 'text', text: value.rendered }]
    },
    async execute(args, exec) {
      const workdir = await resolveWorkdir(ctx, exec)
      const acts = await loadActs()
      let state = createSave(args?.name)
      state = seedFactions(state)
      state = {
        ...state,
        actName: acts.get(state.act)?.name ?? state.actName,
        place: acts.get(state.act)?.place ?? 'zhuojun'
      }
      const scene = scenePayload(state, acts)
      const extra = { pending: scene }
      const committed = await commit(workdir, state, extra, { kind: 'new', at: new Date().toISOString() })
      return {
        digest: committed.digest,
        scene,
        rendered: `${renderDigest(committed.digest)}\n\n【${scene.act}·${scene.title}】\n${scene.narration}\n\n${scene.historical}`
      }
    }
  })
  ctx.tools.register(tool)
}

/**
 * Load the save and fast-forward to the current scene's stamped age.
 *
 * Scenes carry `atAge` when they happen at a specific age (the mulberry tree is
 * a five-year-old; 师事卢植 is fifteen). Without this the player would play a
 * childhood scene at 23 because the clock only advanced between acts.
 */
async function loadReady(workdir, acts) {
  const state = await requireSave(workdir)
  const caught = catchUpToScene(state, acts)
  if (caught === null) {
    return { state, caughtUp: null }
  }
  return { state: caught.state, caughtUp: caught }
}

/** sanguo_status — read the current position. No mutation. */
function registerStatus(ctx) {
  const tool = defineTool({
    name: 'sanguo_status',
    description:
      '读取当前存档的处境：年月、年龄、所在、兵力钱粮、名望信义人才、天下之势、相关人物的态度与记忆、当前场景与选项。' +
      '不改变任何状态。玩家问「我现在什么情况」「我有什么」「这人怎么看我」时用它。',
    parameters: {},
    output: {
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          digest: { type: 'json', required: true },
          scene: { type: 'json', required: true },
          people: { type: 'array', required: true, items: { type: 'json' } },
          rendered: { type: 'string', required: true }
        }
      },
      render: (_args, value) => [{ type: 'text', text: value.rendered }]
    },
    async execute(_args, exec) {
      const workdir = await resolveWorkdir(ctx, exec)
      const acts = await loadActs()
      const ready = await loadReady(workdir, acts)
      const state = ready.state
      if (ready.caughtUp !== null) {
        // A status read that fast-forwarded must PERSIST, or the next tool call
        // would move the clock a second time.
        await save(workdir, state)
      }
      const scene = scenePayload(state, acts)
      const digest = buildDigest(state, { pending: scene })
      const people = rosterOf(state).filter((person) => person.met)
      return {
        digest,
        scene,
        people,
        rendered: `${renderDigest(digest)}\n\n【${scene.act}·${scene.title}】\n${scene.narration}`
      }
    }
  })
  ctx.tools.register(tool)
}

/** sanguo_choose — pick a declared branch at a moral node. No dice. */
function registerChoose(ctx) {
  const tool = defineTool({
    name: 'sanguo_choose',
    description:
      '在当前「抉择」场景里选一个已声明的选项（用 sanguo_status 拿到的选项 id）。' +
      '这类节点不掷骰：后果由引擎按选项数据直接结算，包括名望/信义/人才与钱粮兵力的变化，以及「势」的偏移。' +
      '玩家想做的事如果不在选项里，改用 sanguo_act 自由行动。' +
      '严禁在返回结果之外补充任何数值或后果。',
    parameters: {
      option: {
        type: 'string',
        required: true,
        description: '选项 id（例如 beat / endure / bribe），不是序号。'
      }
    },
    output: {
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          outcome: { type: 'json', required: true },
          digest: { type: 'json', required: true },
          scene: { type: 'json', required: true },
          rendered: { type: 'string', required: true }
        }
      },
      render: (_args, value) => [{ type: 'text', text: value.rendered }]
    },
    async execute(args, exec) {
      const workdir = await resolveWorkdir(ctx, exec)
      const acts = await loadActs()
      const ready = await loadReady(workdir, acts)
      const state = ready.state
      const { act, scene } = currentScene(state, acts)
      if (scene === null) {
        throw new SanguoError('当前没有待决的场景。先 sanguo_advance 推进时间。', 'SANGO_NO_SCENE')
      }
      if (scene.kind !== 'moral') {
        throw new SanguoError(
          `「${scene.title}」不是抉择场景（kind=${scene.kind}），请用 sanguo_act。`,
          'SANGO_WRONG_SCENE_KIND'
        )
      }

      const resolved = chooseBranch(state, act, scene, args?.option)
      let next = nextCursor(resolved.state, acts)
      next = restamp(next, acts, resolved.state)
      const upcoming = scenePayload(next, acts)
      const extra = { pending: upcoming }
      const committed = await commit(workdir, next, extra, {
        kind: 'choose',
        at: new Date().toISOString(),
        act: act?.id,
        scene: scene.id,
        option: args?.option,
        departure: resolved.priced.departure,
        drift: resolved.priced.drift
      })

      const outcome = {
        label: resolved.branch.label,
        note: resolved.branch.note ?? '',
        effects: resolved.effects,
        attributeGain: resolved.attributeGain,
        departure: resolved.priced.departure,
        drift: resolved.priced.drift,
        worldMood: describeDrift(resolved.priced.drift)
      }
      const lines = [
        `【已选】${outcome.label}`,
        outcome.note.length > 0 ? outcome.note : '',
        formatEffects(outcome.effects, outcome.attributeGain),
        outcome.departure ? `（此选偏离史载，势 → ${outcome.drift}，${outcome.worldMood}）` : '',
        '',
        `【${upcoming.act}·${upcoming.title}】`,
        upcoming.narration
      ].filter((line) => line.length > 0)

      return {
        outcome,
        digest: committed.digest,
        scene: upcoming,
        rendered: lines.join('\n')
      }
    }
  })
  ctx.tools.register(tool)
}

/** sanguo_act — a free action, resolved by an ability check. */
function registerAct(ctx) {
  const tool = defineTool({
    name: 'sanguo_act',
    description:
      '玩家尝试任何不在选项里的行动（例如「我带着二十个弟兄夜袭曹营」「我去拜访当地名士」「我拿出全部家财募兵」）。' +
      '把它归结到当前场景的判定上：属性用 wu/tong/zhi/zheng/mei，难度 10-95。' +
      '这两个参数只是「建议」——引擎会把它们夹到合法区间再掷骰，掷骰结果由引擎给出，你无权宣布成败。' +
      '返回的 outcome 里包含骰值、差值、成败与结算后的数值，你只能依据它来叙述。' +
      '如果玩家想做的正是当前场景的某个选项，用 sanguo_choose 更准确。',
    parameters: {
      intent: {
        type: 'string',
        required: true,
        description: '玩家的原话或一句话概括，会写进事件日志。'
      },
      attribute: {
        type: 'string',
        description: '建议用哪个属性判定：wu（武）/ tong（统）/ zhi（智）/ zheng（政）/ mei（魅）。缺省用场景自带属性。'
      },
      difficulty: {
        type: 'number',
        description: '建议难度，10-95。引擎会夹到合法区间。缺省用场景自带难度。'
      }
    },
    output: {
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          outcome: { type: 'json', required: true },
          digest: { type: 'json', required: true },
          scene: { type: 'json', required: true },
          rendered: { type: 'string', required: true }
        }
      },
      render: (_args, value) => [{ type: 'text', text: value.rendered }]
    },
    async execute(args, exec) {
      const workdir = await resolveWorkdir(ctx, exec)
      const acts = await loadActs()
      const ready = await loadReady(workdir, acts)
      const state = ready.state
      const { act, scene } = currentScene(state, acts)
      if (scene === null) {
        throw new SanguoError('当前没有可判定的场景。先 sanguo_advance 推进时间。', 'SANGO_NO_SCENE')
      }

      // A moral scene can still be answered with a free action: the player may
      // refuse every declared option and try something else. That is the whole
      // point of 扮演 mode, so we do not block it — we resolve it as a check
      // against the scene's default attribute and difficulty.
      const hint = {
        attribute: typeof args?.attribute === 'string' ? args.attribute : scene.attribute,
        difficulty: Number.isFinite(args?.difficulty) ? args.difficulty : scene.difficulty
      }
      const resolved = attemptScene(state, act, scene, hint)
      let next = resolved.state
      next = pushLog(next, { kind: 'intent', text: String(args?.intent ?? '') })
      next = nextCursor(next, acts)
      next = restamp(next, acts, state)
      const upcoming = scenePayload(next, acts)
      const extra = { pending: upcoming }
      const committed = await commit(workdir, next, extra, {
        kind: 'act',
        at: new Date().toISOString(),
        act: act?.id,
        scene: scene.id,
        intent: String(args?.intent ?? ''),
        outcome: resolved.result.outcome,
        roll: resolved.result.roll,
        margin: resolved.result.margin
      })

      const outcome = {
        intent: String(args?.intent ?? ''),
        outcome: resolved.result.outcome,
        roll: resolved.result.roll,
        attribute: resolved.result.attribute,
        attributeValue: resolved.result.attributeValue,
        modifierTotal: resolved.result.modifierTotal,
        modifiers: resolved.result.modifiers,
        total: resolved.result.total,
        difficulty: resolved.result.difficulty,
        margin: resolved.result.margin,
        text: resolved.text,
        effects: resolved.effects
      }
      const lines = [
        `【判定】${outcome.attribute} ${outcome.attributeValue} + 骰 ${outcome.roll}` +
          (outcome.modifierTotal !== 0 ? ` ${outcome.modifierTotal > 0 ? '+' : ''}${outcome.modifierTotal}` : '') +
          ` = ${outcome.total}　对　难度 ${outcome.difficulty}　→　${outcomeLabel(outcome.outcome)}`,
        outcome.text,
        formatEffects(outcome.effects, null),
        '',
        `【${upcoming.act}·${upcoming.title}】`,
        upcoming.narration
      ].filter((line) => line.length > 0)

      return {
        outcome,
        digest: committed.digest,
        scene: upcoming,
        rendered: lines.join('\n')
      }
    }
  })
  ctx.tools.register(tool)
}

/** sanguo_advance — let the world run. */
function registerAdvance(ctx) {
  const tool = defineTool({
    name: 'sanguo_advance',
    description:
      '推进时间（一回合为一季），让世界自己走：各势力此消彼长、相邻强弱悬殊者会取地、人物情绪变化、势略微消退。' +
      '玩家说「我什么都不做」「等一等」「过了半年」「我在新野待了几年」时用它。' +
      '即使玩家不行动，历史也会继续——这是本作的核心设定，不要替玩家把时间「跳过」而不调用本工具。',
    parameters: {
      turns: {
        type: 'number',
        description: '推进几季（1-8）。一季 = 三个月。缺省 1。'
      }
    },
    output: {
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          digest: { type: 'json', required: true },
          scene: { type: 'json', required: true },
          events: { type: 'array', required: true, items: { type: 'string' } },
          rendered: { type: 'string', required: true }
        }
      },
      render: (_args, value) => [{ type: 'text', text: value.rendered }]
    },
    async execute(args, exec) {
      const workdir = await resolveWorkdir(ctx, exec)
      const acts = await loadActs()
      const state = await requireSave(workdir)
      const raw = Number.isFinite(args?.turns) ? Math.trunc(args.turns) : 1
      const turns = Math.min(MAX_ADVANCE_TURNS, Math.max(1, raw))

      const advanced = advanceWorld(state, turns)
      const upcoming = scenePayload(advanced.state, acts)
      const extra = { events: advanced.events.map((event) => event.text), pending: upcoming }
      const committed = await commit(workdir, advanced.state, extra, {
        kind: 'advance',
        at: new Date().toISOString(),
        turns,
        events: advanced.events.map((event) => event.text)
      })

      const lines = [
        `【时间】${formatDate(advanced.state.clock)}（${eraOf(advanced.state.clock.year)}）　` +
          `${advanced.state.age}岁`,
        advanced.events.length > 0
          ? `【天下】${advanced.events.map((event) => event.text).join('；')}`
          : '【天下】这一季无大事。',
        `【势】${describeDrift(advanced.state.drift)}（${advanced.state.drift}）`,
        '',
        `【${upcoming.act}·${upcoming.title}】`,
        upcoming.narration
      ]

      return {
        digest: committed.digest,
        scene: upcoming,
        events: advanced.events.map((event) => event.text),
        rendered: lines.join('\n')
      }
    }
  })
  ctx.tools.register(tool)
}

/** Render an effects bag as one readable line. */
function formatEffects(effects, attributeGain) {
  const parts = []
  const labels = {
    fame: '名望',
    trust: '信义',
    talent: '人才',
    gold: '金',
    grain: '粮',
    troops: '兵',
    hp: '身'
  }
  for (const key of Object.keys(labels)) {
    const value = effects?.[key]
    if (!Number.isFinite(value) || value === 0) continue
    parts.push(`${labels[key]} ${value > 0 ? '+' : ''}${value}`)
  }
  if (attributeGain !== null && attributeGain !== undefined) {
    const attrLabels = { wu: '武', tong: '统', zhi: '智', zheng: '政', mei: '魅' }
    for (const key of Object.keys(attributeGain)) {
      const value = attributeGain[key]
      if (!Number.isFinite(value) || value === 0) continue
      parts.push(`${attrLabels[key] ?? key} ${value > 0 ? '+' : ''}${value}`)
    }
  }
  return parts.length > 0 ? `【变化】${parts.join('　')}` : '【变化】无'
}

/** Chinese label for an outcome band. */
function outcomeLabel(outcome) {
  switch (outcome) {
    case 'critical_success': return '大成功'
    case 'success': return '成'
    case 'partial': return '勉强'
    case 'failure': return '败'
    case 'critical_failure': return '大败'
    default: return outcome
  }
}

export { SanguoError, Config, apply, inject, name, formatEffects, outcomeLabel, scenePayload }
